import{z as s,x as A,o as i,c as B,q as l,j as t,D as E,d as p,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"间接效用与支出函数","description":"","frontmatter":{"title":"间接效用与支出函数","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/indirect-utility.md","filePath":"econ/indirect-utility.md","lastUpdated":1791063341000}'),d={name:"econ/indirect-utility.md"};function u(m,a,c,h,C,D){const r=A("Mermaid");return i(),B("div",null,[a[2]||(a[2]=l('<h1 id="间接效用与支出函数" tabindex="-1">间接效用与支出函数 <a class="header-anchor" href="#间接效用与支出函数" aria-label="Permalink to &quot;间接效用与支出函数&quot;">​</a></h1><div class="epigraph"><p>支出函数是达到给定效用的最小开销；间接效用是给定价格与财富时能达到的最大效用。二者互为逆。</p><footer>—— 据 Varian, Microeconomic Analysis；Mas-Colell, Whinston and Green, Microeconomic Theory 第 3 章整理</footer></div><p><a href="/econ/interior-corner">上一课</a>（内点与角点）。给出了 \\(x(p,w)\\) 以及齐次性、瓦尔拉斯定律。本课不重讲预算几何，也不再推导一阶条件。缺口是：后课要把价格效应拆成「沿无差异面滑动」和「换到另一条无差异面」，必须先有一条以效用为约束的对偶问题，以及一个把 \\((p,w)\\) 映成已达效用的值函数。马歇尔需求本身不携带这两套函数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(x(p,w)\\) 回答「在这笔预算上选什么」。政策与福利常问另一句：价格变了，要多少钱才能回到原来的满足？或者：名义财富变了，满足变多少？这两个问题不能靠把 \\(x\\) 再写一遍来回答，因为 \\(x\\) 的坐标是商品，不是效用，也不是钱。缺口是引进两个值函数。</p><p><span class="marginnote">「间接」效用不是另一种效用，是「幸福仪表盘的读数」：原始偏好问「你想要什么」，间接效用直接读表——给定价格和钱包，你能到达的幸福高度是多少。价格涨一格或钱包缩一截，读数就掉一格。支出函数则反着读：指定想要的高度，问最便宜的到达成本。</span></p><p>间接效用 \\(v(p,w)=u\\bigl(x(p,w)\\bigr)\\)，即最优值。支出函数</p> \\[e(p,u)=\\min_x\\bigl\\{p\\cdot x:u(x)\\ge u\\bigr\\}, \\]<p>即达到效用 \\(u\\) 的最便宜账单。希克斯需求 \\(h(p,u)\\) 是这个最小问题的解。本课的任务是钉死 \\(v\\) 与 \\(e\\) 互逆、以及它们对价格的导数如何回到需求——罗伊恒等式与谢泼德引理。斯勒茨基分解下一课才写。</p><h3 id="对偶不是另一套偏好" tabindex="-1">对偶不是另一套偏好 <a class="header-anchor" href="#对偶不是另一套偏好" aria-label="Permalink to &quot;对偶不是另一套偏好&quot;">​</a></h3><p>支出最小化用的仍是同一 \\(u\\)，同一 \\(\\succsim\\)。改的是约束：从「钱给定、效用最大」换成「效用给定、钱最小」。局部非餍足下，最优处 \\(u\\bigl(h(p,u)\\bigr)=u\\)，且 \\(e\\bigl(p,v(p,w)\\bigr)=w\\)。对偶缺口一旦补上，马歇尔与希克斯只是同一偏好的两种参数化。</p><p><span class="marginnote">\\(v\\) 随 \\(u\\) 的单调变换而变，\\(e\\) 的「效用刻度」也随之改。希克斯需求本身仍是序数对象：它只依赖于无差异集，不依赖于刻度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(v\\) 对 \\(p\\) 拟凸、对 \\(w\\) 递增，且 \\((p,w)\\) 零次齐次——因为 \\(x\\) 零次齐次，\\(u(x)\\) 只依赖比值。\\(e\\) 对 \\(p\\) 凹、一次齐次、对 \\(u\\) 递增。凹性来自：两个价格的平均去买，不会比分别买更贵。这些形状后课用来证明斯勒茨基矩阵负半定。</p><p>包络定理给出导数，不必把最优束对价格再全微分。谢泼德引理：\\(\\nabla_p e(p,u)=h(p,u)\\)。罗伊恒等式：</p> \\[x_i(p,w)=-\\frac{\\partial v/\\partial p_i}{\\partial v/\\partial w}. \\]<p>直观是：涨价的效用损失，除以财富的边际效用，等于必须减掉的消费。本课把这两条当对偶的可操作接口，不把包络证明重写一遍。</p>',17)),(i(),t(o,null,{default:E(()=>[n(r,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E9%A9%AC%E6%AD%87%E5%B0%94%E9%9C%80%E6%B1%82%20x(p%2Cw)%22%5D%20--%3E%20V%5B%22%E9%97%B4%E6%8E%A5%E6%95%88%E7%94%A8%20v(p%2Cw)%22%5D%0A%20%20U%5B%22%E6%95%88%E7%94%A8%E7%BA%A6%E6%9D%9F%20u%22%5D%20--%3E%20E%5B%22%E6%94%AF%E5%87%BA%E5%87%BD%E6%95%B0%20e(p%2Cu)%22%5D%0A%20%20E%20--%3E%20H%5B%22%E5%B8%8C%E5%85%8B%E6%96%AF%E9%9C%80%E6%B1%82%20h(p%2Cu)%22%5D%0A%20%20V%20--%3E%20ROY%5B%22%E7%BD%97%E4%BC%8A%E6%81%92%E7%AD%89%E5%BC%8F%22%5D%0A%20%20H%20--%3E%20SHEP%5B%22%E8%B0%A2%E6%B3%BC%E5%BE%B7%E5%BC%95%E7%90%86%22%5D%0A%20%20ROY%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%96%AF%E5%8B%92%E8%8C%A8%E5%9F%BA%E5%88%86%E8%A7%A3%22%5D%0A%20%20SHEP%20--%3E%20LATER%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"恒等式 \\(x(p,w)=h\\bigl(p,v(p,w)\\bigr)\\) 与 \\(h(p,u)=x\\bigl(p,e(p,u)\\bigr)\\) 把两条需求焊在一起。下一课对 \\(p\\) 求导，交叉项就是收入效应。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[p("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"值函数比原始需求更光滑、更好认。\\(e\\) 对 \\(p\\) 凹，立刻推出希克斯需求向下倾斜：自价格替代效应非正。马歇尔需求没有这层保护，因为收入效应可以翻号。这就是为什么补偿变化、等价变化用 \\(e\\) 来写，而不用 \\(x\\) 的积分乱加。",-1)),a[6]||(a[6]=e("p",null,"福利比较在本课只开一个口：价格从 \\(p^0\\) 变到 \\(p^1\\)，补偿变化是 \\(e(p^1,u^0)-e(p^0,u^0)\\)。这是钱，可以加总到一个人的两次预算上，仍然不是人际效用。后课税收归宿会再借这个口，本课不展开公共财政。",-1)),a[7]||(a[7]=e("p",null,[e("span",{class:"marginnote"},"数字实例：你每月买 30 杯咖啡、每杯 10 元；涨到 12 元后，按原效用水平重新挑最便宜的消费组合，月开销变成 336 元——多出的 36 元就是补偿变化，意思是「补你 36 块，涨价对你的伤害就归零」。注意它一般不等于按原数量算的 60 元：你还会少喝几杯来省钱。")],-1)),(i(),t(o,null,{default:E(()=>[n(r,{id:"mermaid-61",class:"mermaid",graph:"flowchart%20TD%0A%20%20P0%5B%22%E5%8E%9F%E4%BB%B7%E6%A0%BC%20p0%20%E4%B8%8E%E5%8E%9F%E6%95%88%E7%94%A8%20u0%22%5D%20--%3E%20Q%5B%22%E9%97%AE%3A%20%E6%B6%A8%E4%BB%B7%E5%90%8E%E8%A1%A5%E5%A4%9A%E5%B0%91%E9%92%B1%E6%89%8D%E4%B8%8D%E4%BA%8F%3F%22%5D%0A%20%20Q%20--%3E%20E1%5B%22%E5%9C%A8%20u0%20%E4%B8%8B%E6%8C%89%E6%96%B0%E4%BB%B7%E6%A0%BC%20p1%20%E8%AE%B0%E6%9C%80%E5%B0%8F%E8%B4%A6%E5%8D%95%22%5D%0A%20%20E1%20--%3E%20CV%5B%22CV%20%3D%20e(p1%2Cu0)%20-%20e(p0%2Cu0)%22%5D%0A%20%20CV%20--%3E%20MONEY%5B%22%E7%AD%94%E6%A1%88%E6%98%AF%E9%92%B1%2C%20%E4%B8%8D%E6%98%AF%E6%95%88%E7%94%A8%E5%88%BB%E5%BA%A6%22%5D%0A%20%20CV%20--%3E%20USE%5B%22%E5%8F%AF%E5%8A%A0%E8%BF%9B%E5%90%8C%E4%B8%80%E4%B8%AA%E4%BA%BA%E7%9A%84%E9%A2%84%E7%AE%97%2C%20%E4%B8%8D%E5%81%9A%E4%BA%BA%E9%99%85%E6%AF%94%E8%BE%83%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[p(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=l('<p><span class="marginnote">拟线性效用使 \\(e\\) 在计价物与效用之间仿射，收入效应集中在计价物上。这是后课局部均衡常用的刀，不是一般形状。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>\\(v\\) 与 \\(e\\) 要求最优存在。价格为零或偏好在边界上不满足局部非餍足时，最小值可以是 \\(0\\) 或达不到。角点上谢泼德引理改成超梯度：支出函数仍凹，导数是对应。可微公式只在内点正则处使用。</p><p>也不要把间接效用当成「可观测的幸福指数」。观测到的是 \\((p,w,x)\\)；\\(v\\) 是模型里的值。显示偏好课会问：这些观测是否与某一 \\(u\\) 一致。本课仍走「偏好 → 对偶函数」方向。</p><p><span class="marginnote">初学者容易把 \\(v\\) 当成问卷满意度那样能直接量到的东西，实际上能观测的只有价格、钱包和买了什么，\\(v\\) 是模型算出来的影子。这一步做错，就会拿主观幸福调查去「验证」效用理论——走错了门：显示偏好要检验的是行为自洽，不是感觉。</span></p><p>补偿变化与等价变化用 \\(e\\) 定义，路径无关靠的是下一课才写清的 \\(S\\) 对称。本课只把值函数准备好，不把福利积分提前做完。价格指数后课会再借 \\(e\\)，对象是宏观核算，不是这里的消费者对偶。</p><p>后课默认：可以自由使用 \\(v\\)、\\(e\\)、\\(h\\)，以及罗伊、谢泼德两条导数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>间接效用是马歇尔问题的值；支出函数是效用约束下的最小账单。</li><li>二者互逆；\\(x\\) 与 \\(h\\) 只是同一偏好的两种参数化。</li><li>谢泼德引理与罗伊恒等式用包络把需求从值函数读出。</li><li>希克斯自价格效应非正；马歇尔效应的符号留给斯勒茨基。</li><li>出处：Varian, <em>Microeconomic Analysis</em>；Mas-Colell, Whinston and Green 第 3 章。</li></ul>',9))])}const f=s(d,[["render",u]]);export{x as __pageData,f as default};
